export const getSuggestedCourses = (department?: string, level?: string): SeedCourse[] => {
  if (!department && !level) return SAMPLE_COURSES.slice(0, 8);
  
  const dept = (department || '').toLowerCase().trim();
  const lvl = String(level || '').trim();

  return SAMPLE_COURSES.filter((c) => {
    const matchDept = !dept || !c.departments?.length || c.departments.some(d => d.toLowerCase().includes(dept) || dept.includes(d.toLowerCase()));
    const matchLvl = !lvl || !c.levels?.length || c.levels.map(String).includes(lvl);
    return matchDept && matchLvl;
  });
};

export const seedUserSelectedCourses = async (selectedIds: string[]) => {
  try {
    const coursesToSeed = SAMPLE_COURSES.filter(c => selectedIds.includes(c.id) || selectedIds.includes(c.code));
    for (const course of coursesToSeed) {
      const { weeks, ...courseData } = course;
      await setDoc(doc(db, 'courses', course.id), courseData, { merge: true });

      for (const week of weeks) {
        await setDoc(
          doc(db, 'courses', course.id, 'weeks', week.id),
          week,
          { merge: true }
        );
      }
    }
    return true;
  } catch (error) {
    console.error('Failed to seed selected courses:', error);
    return false;
  }
};

export const seedSampleCourses = async () => {
  try {
    for (const course of SAMPLE_COURSES) {
      const { weeks, ...courseData } = course;
      await setDoc(doc(db, 'courses', course.id), courseData, { merge: true });

      for (const week of weeks) {
        await setDoc(
          doc(db, 'courses', course.id, 'weeks', week.id),
          week,
          { merge: true }
        );
      }
    }
    console.log('Successfully seeded all 146 engineering courses!');
    return true;
  } catch (error) {
    console.error('Failed to seed sample courses:', error);
    return false;
  }
};

